     5  SDB_API void sdb_ns_lock(Sdb *s, int lock, int depth) {
     6          SdbListIter *it;
     7          SdbNs *ns;
     8          s->ns_lock = lock;
     9          if (depth) { // handles -1 as infinite
    10                  ls_foreach (s->ns, it, ns) {
    11                          sdb_ns_lock (ns->sdb, lock, depth-1);
    12                  }
    13          }
    14  }
