    16  static int in_list(SdbList *list, void *item) {
    17          SdbNs *ns;
    18          SdbListIter *it;
    19          if (list && item)
    20          ls_foreach (list, it, ns) {
    21                  if (item == ns) {
    22                          return 1;
    23                  }
    24          }
    25          return 0;
    26  }
