    73  SDB_API void sdb_ns_free(Sdb *s) {
    74          SdbList *list;
    75          if (!s) {
    76                  return;
    77          }
    78          list = ls_new ();
    79          list->free = NULL;
    80          ns_free (s, list);
    81          ls_free (list);
    82          ls_free (s->ns);
    83          s->ns = NULL;
    84  }
