   177  SDB_API Sdb *sdb_ns(Sdb *s, const char *name, int create) {
   178          SdbListIter *it;
   179          SdbNs *ns;
   180          ut32 hash;
   181          if (!s || !name || !*name) {
   182                  return NULL;
   183          }
   184          hash = sdb_hash (name);
   185          ls_foreach (s->ns, it, ns) {
   186                  if (ns->hash == hash) {
   187                          return ns->sdb;
   188                  }
   189          }
   190          if (!create) {
   191                  return NULL;
   192          }
   193          if (s->ns_lock) {
   194                  return NULL;
   195          }
   196          ns = sdb_ns_new (s, name, hash);
   197          if (!ns) {
   198                  return NULL;
   199          }
   200          ls_append (s->ns, ns);
   201          return ns->sdb;
   202  }
